import {b,shells} from './math.js';
export const C={green:'#a5dfa5',blue:'#7ec9f4',gold:'#f0c775',pink:'#edb4c4',white:'#e3ece5',dark:'#8eacb6'};
export const reflect=(n,s=1)=>{let a=((n+s)%(4*s)+4*s)%(4*s);return a<2*s?a-s:3*s-a};
export const read=(en,hi,value,unit='')=>({label:b(en,hi),value:String(value),unit});
export function particles(g,t,count=48,mode=2,speed=1){g.box(0,0,0,1,1,1);for(let i=0;i<count;i++){let x=(i%4-1.5)*.43,y=(Math.floor(i/4)%4-1.5)*.43,z=(Math.floor(i/16)-1)*.5;if(mode===0){x+=.035*Math.sin(t*speed*8+i);y+=.035*Math.cos(t*speed*7+i)}else{x=reflect(x+t*speed*Math.sin(i*7+1)*.32,.88);y=reflect(y+t*speed*Math.cos(i*5+2)*.32,.88);z=reflect(z+t*speed*Math.sin(i*3+3)*.32,.88);if(mode===1)y=y*.42+.5}g.sphere(x,y,z,mode===2?.045:.06,mode===2?C.gold:C.green)}}
export function molecule(g,type,n=1){let layouts={water:[[0,0,0,'O'],[-.42,.33,0,'H'],[.42,.33,0,'H']],ammonia:[[0,-.2,0,'N'],[-.42,.25,.3,'H'],[.42,.25,.3,'H'],[0,.25,-.42,'H']],'carbon-dioxide':[[0,0,0,'C'],[-.6,0,0,'O'],[.6,0,0,'O']]};for(let j=0;j<n;j++){let ox=n>1?(j%2-.5)*1.45:0,oy=n>2?(Math.floor(j/2)-.5)*1.1:0,scale=n>1?.85:1.2,pts=layouts[type];pts.forEach((q,i)=>{let color=q[3]==='H'?C.white:q[3]==='O'?C.green:q[3]==='N'?C.blue:C.dark;g.sphere(ox+q[0]*scale,oy+q[1]*scale,q[2]*scale,q[3]==='H'?.1:.18,color,n===1?q[3]:null);if(i)g.line([ox+pts[0][0]*scale,oy+pts[0][1]*scale,pts[0][2]*scale],[ox+q[0]*scale,oy+q[1]*scale,q[2]*scale],C.gold,3)})}}
export function atom(g,Z,e,t,neutrons=Z){g.sphere(0,0,0,.21,C.gold,b('Nucleus','नाभिक'));shells(e).forEach((count,k)=>{let r=.43+k*.39;g.ring(r,0,'#74aa93');for(let i=0;i<count;i++){let a=t*.45/(k+1)+i*2*Math.PI/count;g.sphere(Math.cos(a)*r,0,Math.sin(a)*r,.044,C.blue)}});g.text(0,1.1,0,b(`${Z} protons, ${neutrons} neutrons`,`${Z} प्रोटॉन, ${neutrons} न्यूट्रॉन`))}
export const organelles=[b('Nucleus','केन्द्रक'),b('Mitochondrion','माइटोकॉन्ड्रिया'),b('Chloroplast','हरितलवक'),b('Vacuole','रिक्तिका'),b('Golgi apparatus','गॉल्जी तन्त्र'),b('Cell membrane','कोशिका झिल्ली')];
export function cell(g,plant=true,focus=-1,scale=1){if(plant)g.box(0,0,0,1.16,.86,.7,C.green);for(let j=0;j<3;j++){let prev;for(let i=0;i<=40;i++){let a=i/40*Math.PI*2,q=j===0?[Math.cos(a)*1.06*scale,Math.sin(a)*.76*scale,0]:j===1?[Math.cos(a)*1.06*scale,0,Math.sin(a)*.6*scale]:[0,Math.cos(a)*.76*scale,Math.sin(a)*.6*scale];if(prev)g.line(prev,q,focus===5?C.gold:'#7db9a3',focus===5?3:1);prev=q;}}let parts=[[-.5,-.15,0,.24,C.blue],[.52,.42,.1,.12,C.gold],[.66,-.4,.1,.12,C.green],[.15,.05,0,.35,'#86cbbf'],[-.12,-.5,.1,.13,C.pink]];parts.forEach((q,i)=>{if(!plant&&(i===2||i===3))return;let radius=q[3]*(focus===i?1.18:1);g.sphere(q[0]*scale,q[1]*scale,q[2]*scale,radius*scale,q[4],focus===i?organelles[i]:null,i);if(i===1){g.sphere(-.5,.4,-.1,.1,C.gold,null,1)}if(i===4)for(let l=0;l<3;l++)g.line([-.35,-.48+l*.07,.1],[.1,-.48+l*.07,.1],C.pink,3)});if(focus===5)g.text(0,1.05,0,organelles[5])}
export function neuron(g,t=0,speed=1){g.sphere(-.65,0,0,.19,C.blue,b('Cell body','कोशिकाकाय'));for(let i=0;i<5;i++)g.line([-.78,0,0],[-1.3,(i-2)*.22,.1],C.green,2);g.line([-.46,0,0],[1.3,0,0],C.gold,3);let x=-.4+(t*speed%1.7);g.sphere(x,0,0,.065,C.pink);g.text(.55,.42,0,b('Axon','अक्षतन्तु'));g.arrow([-.35,-.4,0],[1,-.4,0],C.pink)}
export function plants(g,t,kind=0,stage=3){g.box(0,.8,0,1.3,.11,.9,'#bca171');for(let row=0;row<3;row++)for(let i=0;i<4;i++){let x=-.9+i*.6,z=-.6+row*.6,h=.3+stage*.12,color=kind===1&&row%2?C.gold:C.green;g.line([x,.65,z],[x,.65-h,z],color,3);g.sphere(x-.1,.65-h*.65,z,.09,color);g.sphere(x+.1,.65-h*.85,z,.09,color);g.line([x,.8,z],[x-.08,1.05,z],C.gold);g.sphere(x,1.03-(t*.3+i*.13)% .5,z,.025,C.blue)}}
